InputTimeOutCMD[0](
		WaitCheckEnable := g_bWaitInputPortM,
		WaitInputPortAlarmTime :=g_nWaitInputPortAlarmTime,
		WaitInputPortNumber := g_nWaitInputPortNumber,
		WaitInputPortBoardType := g_nWaitInputPortBoardType,
		WaitInputPortJudgeType := g_nWaitInputPortJudgeType,
		WaitInputPortExecuteType := g_nWaitInputPortExecuteType,
        WaitCheckMode := 0,
        ChangeOutput := FALSE,
        UpdateIndex :=0,
		OutPut => M.ENABLE[302]);

FOR Index := 1 TO 11 BY 1 DO
	InputTimeOutCMD[Index](
		WaitCheckEnable := g_ParallelCMDData[Index-1].TriggerFlag,
		WaitInputPortAlarmTime := g_ParallelCMDData[Index-1].Q,
		WaitInputPortNumber := g_ParallelCMDData[Index-1].P,
		WaitInputPortBoardType := g_ParallelCMDData[Index-1].J,
		WaitInputPortJudgeType := g_ParallelCMDData[Index-1].I,
		WaitInputPortExecuteType := g_ParallelCMDData[Index-1].K,
        WaitCheckMode := 1,
        ChangeOutput := g_ParallelCMDData[Index-1].ChangeFlag,
        UpdateIndex :=Index,
		OutPut => g_ParallelCMDData[Index-1].FinishFlag);
  (*保存执行过的M代码清单*)
	SaveMCodeExecute(
	SaveFlag := g_ParallelCMDData[Index-1].TriggerFlag,
	Index := g_nSaveMControlTotalNumber,
	MCode := 302,
	MP := g_ParallelCMDData[Index-1].P,
	MQ := g_ParallelCMDData[Index-1].Q,
	MI := g_ParallelCMDData[Index-1].I,
	MJ := g_ParallelCMDData[Index-1].J,
	MK := g_ParallelCMDData[Index-1].K,
	MH := 1.0,
	LogTime := GET_SYSTEM_TIME(0)
	);
	Rtring_MCodeExecute(CLK := g_ParallelCMDData[Index-1].TriggerFlag);
	IF Rtring_MCodeExecute.Q THEN
		g_nSaveMControlTotalNumber := g_nSaveMControlTotalNumber + 1;
		IF g_nSaveMControlTotalNumber >= 10 THEN
			g_nSaveMControlTotalNumber := 0;
		END_IF;
		g_ParallelCMDData[Index-1].TriggerFlag := FALSE;
	END_IF;        
  END_FOR;


(*关闭触发标志,只保留一个周期*)
g_bWaitInputPortM := FALSE;



(*检测M327的信号*)
Rtring_triggerM327(CLK := g_bM327ControlTriggered);
IF Rtring_triggerM327.Q THEN
  nM327Input := LREAL_TO_INT(M.PARAMETER_P[327]);
  g_bM327ControlTriggered := FALSE;
  g_boFindEage := FALSE;
  nM327CheckState := 10;
  M.ENABLE[327] := 0;
END_IF;


CASE nM327CheckState OF
  0:
	nM327CheckState :=0;
  10:
	IF BoardInPutArray.BoolArr[nM327Input-1] THEN
      g_boFindEage := true;(*给引脚赋true，让cnc收到寻边完成信号停止移动*)
      nM327CheckState :=0;
    END_IF;

END_CASE;
IF g_bPlcResetBuffer THEN
  g_bWaitInputPorTimeOutAlarm := FALSE;
  g_bWaitInputPorTimeOutContinueAlarm:= FALSE;
  nWaitState := 0;
  g_bWaitInputPortM := FALSE;
  g_bExecuteFinishedM302 := FALSE;
  nM327CheckState :=0;
  g_bM327ControlTriggered := FALSE;
  (*如果开启了并行实时刷新的就不要关了,可能在实时刷新*)
  FOR Index := 1 TO 11 BY 1 DO
        IF g_bRealTimeUpdateParallePLC AND g_bRealTimeUpdateParallePLCExecuteFlag THEN
			IF g_nRealTimeUpdateParallePLCIndex <> Index THEN
				g_ParallelCMDData[Index-1].FinishFlag := 1; 
				g_ParallelCMDData[Index-1].TriggerFlag := FALSE; 
            END_IF;
		ELSE
			g_ParallelCMDData[Index-1].FinishFlag := 1; 
			g_ParallelCMDData[Index-1].TriggerFlag := FALSE; 
		END_IF;	
  END_FOR;


END_IF;
